import{_ as r,C as s,o,c as i,j as e,a,b as l,w as d,E as p,a3 as u,a2 as c}from"./chunks/framework.CIOzaBgM.js";const h="/ragflow-book/assets/v01-chunks.DEZYDZtp.png",k=JSON.parse('{"title":"第 1 章 RAG 要解决什么问题，RAGFlow 押注在哪","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/01-why-rag.md","filePath":"chapters/01-why-rag.md","lastUpdated":1791471399000}'),g={name:"chapters/01-why-rag.md"};function m(q,t,b,A,E,_){const n=s("Mermaid");return o(),i("div",null,[t[1]||(t[1]=e("h1",{id:"第-1-章-rag-要解决什么问题-ragflow-押注在哪",tabindex:"-1"},[a("第 1 章 RAG 要解决什么问题，RAGFlow 押注在哪 "),e("a",{class:"header-anchor",href:"#第-1-章-rag-要解决什么问题-ragflow-押注在哪","aria-label":'Permalink to "第 1 章 RAG 要解决什么问题，RAGFlow 押注在哪"'},"​")],-1)),t[2]||(t[2]=e("blockquote",null,[e("p",null,'本章目标：说清楚一个"能用"的知识库要过哪几关、在每一关会怎么失败，以及 RAGFlow 选择在哪几处下重注。 前置：第 0 章。对应代码：无（本章用后面各版本里真实跑出来的结果举例）。')],-1)),t[3]||(t[3]=e("h2",{id:"_1-1-最朴素的-rag",tabindex:"-1"},[a("1.1 最朴素的 RAG "),e("a",{class:"header-anchor",href:"#_1-1-最朴素的-rag","aria-label":'Permalink to "1.1 最朴素的 RAG"'},"​")],-1)),(o(),l(u,null,{default:d(()=>[p(n,{id:"mermaid-11",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20D%5B%E6%96%87%E6%A1%A3%5D%20--%3E%7C%E5%88%87%E5%9D%97%7C%20C%5Bchunks%5D%0A%20%20%20%20C%20--%3E%7Cembedding%7C%20V%5B(%E5%90%91%E9%87%8F%E5%BA%93)%5D%0A%20%20%20%20Q%5B%E9%97%AE%E9%A2%98%5D%20--%3E%7Cembedding%7C%20QV%5B%E9%97%AE%E9%A2%98%E5%90%91%E9%87%8F%5D%0A%20%20%20%20QV%20--%3E%7C%E6%9C%80%E8%BF%91%E9%82%BB%7C%20V%0A%20%20%20%20V%20--%3E%7Ctop-k%20chunks%7C%20P%5B%E6%8B%BC%E8%BF%9B%E6%8F%90%E7%A4%BA%E8%AF%8D%5D%0A%20%20%20%20P%20--%3E%20L%5BLLM%5D%20--%3E%20A%5B%E5%9B%9E%E7%AD%94%5D%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[a(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=c('<p>这条链路二十行代码就能搭出来：按固定长度切块，算 embedding，取余弦最高的 k 块拼进提示词。它能跑出 demo，但一旦换成真实文档，就会在三个地方出错。下面三个例子都来自本书配套代码在真实运行中的输出，不是虚构的。</p><h2 id="_1-2-第一类失败-切坏了" tabindex="-1">1.2 第一类失败：切坏了 <a class="header-anchor" href="#_1-2-第一类失败-切坏了" aria-label="Permalink to &quot;1.2 第一类失败：切坏了&quot;">​</a></h2><p>mini-ragflow v0.1 的切分很朴素：在换行和句号处切开，然后按 token 预算往一块里塞。用它切《星河咖啡机用户手册》，第 1 块装下了第 1~5 节的开头，第 2 块从&quot;当除垢指示灯亮起时……&quot;开始：</p><p><img src="'+h+`" alt="图 1-1：v0.1 的朴素切分，第 2 块从一节的中间开始，丢了“5. 清洁与除垢”这个标题。"></p><p><em>图 1-1：v0.1 的朴素切分。#1 块从小节中间开始，&quot;## 5. 清洁与除垢&quot;这个标题被留在了 #0 块里。</em></p><p>问题在于：#1 块讲的是除垢步骤，但它的文本里既没有&quot;清洁与除垢&quot;，也没有&quot;咖啡机&quot;。用户问&quot;咖啡机怎么除垢&quot;，关键词匹配会被 #0 块里的标题吸走，向量相似度也因为缺少上下文而变低。<strong>文档的结构（标题、条款、表格、问答对）是检索质量的上限</strong>，切块时一旦丢掉，后面靠任何排序技巧都补不回来。</p><p>第 9 章会换上按标题层级切分的方法：每一块都带上自己所属的标题路径（<code># 星河 S1 咖啡机用户手册 / ## 5. 清洁与除垢</code>）。</p><h2 id="_1-3-第二类失败-找不到" tabindex="-1">1.3 第二类失败：找不到 <a class="header-anchor" href="#_1-3-第二类失败-找不到" aria-label="Permalink to &quot;1.3 第二类失败：找不到&quot;">​</a></h2><p>v0.3 的检索引擎刚写好时，有一个问题怎么问都搜不到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q: 工作满10年年假有几天</span></span>
<span class="line"><span>top = &lt;none&gt;   (pass 1: kNN filtered by full-text, min_match=0.3, 1 hits)</span></span></code></pre></div><p>原因藏在分词里：mini-ragflow 没有中文词典，用二字切分（bigram）来近似。&quot;年假有几天&quot;被切成&quot;年假 / 假有 / 有几 / 几天&quot;，其中&quot;假有&quot;&quot;有几&quot;是跨词的伪词。它们在语料里从没出现过，按 IDF 公式反而拿到了最高的权重，结果把真正的关键词&quot;年假&quot;的分量稀释掉了（第 12 章会讲修法）。</p><p>另一个&quot;找不到&quot;来自 embedding 模型本身。同一句&quot;咖啡机怎么除垢？&quot;，分别和三段文本算余弦：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nomic-embed-text  q·[除垢步骤, 年假规定, 咖啡粉说明] = [0.726, 0.711, 0.719]</span></span>
<span class="line"><span>bge-m3            q·[除垢步骤, 年假规定, 咖啡粉说明] = [0.654, 0.335, 0.509]</span></span></code></pre></div><p><code>nomic-embed-text</code> 对中文几乎没有区分度：相关和不相关的文本得分一样高。<strong>检索要关键词和向量两条腿走路</strong>，任何一条腿都不能单独信任。</p><h2 id="_1-4-第三类失败-答不准" tabindex="-1">1.4 第三类失败：答不准 <a class="header-anchor" href="#_1-4-第三类失败-答不准" aria-label="Permalink to &quot;1.4 第三类失败：答不准&quot;">​</a></h2><p>v0.5 里有两份手册：S1 和 S2，型号不同，保修条款也不同。问&quot;S1 的保修期多久？&quot;，真实模型（qwen2.5:3b）是这样回答的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>星河 S1 咖啡机的保修期如下：- 整机保修期为 2 年。- 研磨器保修期为 5 年。</span></span></code></pre></div><p>&quot;研磨器保修 5 年&quot;是 S2 的条款。检索把两份手册的保修段落一起送进了提示词，模型就把它们混在了一起。修法不在模型上，而在检索上：给文档打上&quot;产品型号&quot;元数据，问题里提到 S1，就只在 S1 的文档里检索（第 19 章）。</p><p>还有一种&quot;答不准&quot;更隐蔽：模型回答&quot;The answer is not found in the dataset.&quot;，系统却用向量相似度给这句拒答挂上了一条引用。用户看到引用会以为答案有出处（第 16 章）。</p><h2 id="_1-5-ragflow-押注在哪" tabindex="-1">1.5 RAGFlow 押注在哪 <a class="header-anchor" href="#_1-5-ragflow-押注在哪" aria-label="Permalink to &quot;1.5 RAGFlow 押注在哪&quot;">​</a></h2><p>RAGFlow 的 README（<code>README.md:104</code> 起）列出了它的核心特性。和上面三类失败对照着看：</p><table tabindex="0"><thead><tr><th>README 的说法</th><th>对应的失败</th><th>本书章节</th></tr></thead><tbody><tr><td><strong>&quot;Quality in, quality out&quot;</strong>：基于深度文档理解，从格式复杂的非结构化数据里抽取知识</td><td>切坏了</td><td>第 8 章 DeepDoc</td></tr><tr><td><strong>Template-based chunking</strong>：可解释、可选的切分模板</td><td>切坏了</td><td>第 7、9 章</td></tr><tr><td><strong>Multiple recall paired with fused re-ranking</strong></td><td>找不到</td><td>第 12、13 章</td></tr><tr><td><strong>Grounded citations with reduced hallucinations</strong>：切块可视化、可追溯的引用</td><td>答不准</td><td>第 14、16、17 章</td></tr><tr><td><strong>Knowledge Compilation</strong>：Wiki、图谱、树（RAPTOR）、思维导图……</td><td>找不到（宏观问题）</td><td>第 20 章</td></tr><tr><td><strong>Agentic Retrieval</strong>：多步检索、拆解问题、核验证据</td><td>答不准（复杂问题）</td><td>第 21 章</td></tr><tr><td><strong>Go-native service architecture</strong>：API、Admin、Ingestor、Syncer 统一由 Go 服务提供</td><td>平台化</td><td>第 2、24、25 章</td></tr></tbody></table><p>可以把 RAGFlow 的取舍概括成一句话：<strong>把力气花在入库这一侧</strong>。DeepDoc 用 ONNX 模型做版面识别、OCR 和表格结构识别；切分不是一个固定算法，而是一组可选模板（通用、书籍、法规、问答、表格……），而且每个模板都是一张可编辑的流水线图。检索和生成这一侧，则用&quot;关键词 + 向量&quot;两阶段打分和&quot;强制引用&quot;来兜底。</p><p>这也决定了本书的篇幅分配：入库（Part II、III）和检索（Part IV）占了一半。</p><h2 id="_1-6-本书怎么覆盖这些押注" tabindex="-1">1.6 本书怎么覆盖这些押注 <a class="header-anchor" href="#_1-6-本书怎么覆盖这些押注" aria-label="Permalink to &quot;1.6 本书怎么覆盖这些押注&quot;">​</a></h2><table tabindex="0"><thead><tr><th>押注</th><th>mini-ragflow 做到什么程度</th></tr></thead><tbody><tr><td>深度文档理解</td><td>只做文本层解析（docx/html/md/xlsx/pdf 文本层），不复刻 DeepDoc 的模型；第 8 章读源码</td></tr><tr><td>模板化切分</td><td>6 个模板，5 种切分算法，DSL 可配置</td></tr><tr><td>融合重排</td><td>完整复刻 RAGFlow ES 路径的两阶段打分，另外实现 Infinity 式加权融合作对照</td></tr><tr><td>可溯源引用</td><td><code>[ID:n]</code> 协议、格式修复、向量回填、拒答不引用、前端悬浮</td></tr><tr><td>知识编译</td><td>实现 RAPTOR（树），其余读源码</td></tr><tr><td>Agentic 检索</td><td>只读源码</td></tr></tbody></table><h2 id="_1-7-练习" tabindex="-1">1.7 练习 <a class="header-anchor" href="#_1-7-练习" aria-label="Permalink to &quot;1.7 练习&quot;">​</a></h2><ol><li><strong>巩固</strong>：用自己的话解释，为什么&quot;给每个 chunk 带上标题路径&quot;既能帮关键词检索，也能帮向量检索。</li><li><strong>扩展</strong>：设计一个能让 1.4 节&quot;型号混淆&quot;重现的最小数据集（两份文档、一个问题），再想想除了元数据过滤，还有哪些办法能缓解。</li><li><strong>读源码</strong>：RAGFlow 的 <code>internal/ingestion/pipeline/template/</code> 下有 12 个模板 JSON。打开 <code>ingestion_pipeline_laws.json</code> 和 <code>ingestion_pipeline_general.json</code>，比较它们的切分组件和参数有什么不同。</li></ol><h2 id="_1-8-延伸阅读" tabindex="-1">1.8 延伸阅读 <a class="header-anchor" href="#_1-8-延伸阅读" aria-label="Permalink to &quot;1.8 延伸阅读&quot;">​</a></h2><ul><li>RAGFlow <code>README.md</code> 的 Key Features 一节</li><li>Lewis et al., <em>Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks</em>, 2020</li><li>Sarthi et al., <em>RAPTOR: Recursive Abstractive Processing for Tree-Organized Retrieval</em>, 2024</li></ul>`,30))])}const R=r(g,[["render",m]]);export{k as __pageData,R as default};
